/* Only MiniMax uppercut decorative upward streaks; physics unchanged. */
(()=>{const role=window.ArenaCharacterModules.minimax,previous=role.drawEffect;role.drawEffect=function(c,e,env){if(e.kind!=='swing'||e.characterId!=='minimax'||e.stage!==2)return previous?.(c,e,env)??false;const u=Math.max(0,Math.min(1,env.u??1-e.life/e.max)),dir=e.dir||1;c.save();c.translate(e.x+dir*14,e.y-90);c.scale(dir,1);c.globalAlpha=(1-u)*.8;c.strokeStyle='#ffd29c';c.lineWidth=1.5;c.beginPath();c.rect(-10,-24,76,48);c.clip();for(let j=0;j<3;j++){let x=2+j*7;c.beginPath();c.moveTo(x+5,12-u*10);c.quadraticCurveTo(x-4,2-u*10,x,-9-u*10);c.stroke();}c.restore();return true;};})();
